export type LogType = "DEBUG" | "INFO" | "ERROR";
export interface LogParams {
    type?: LogType;
    message: unknown;
    logId?: string;
    payload?: any;
    statusCode?: number;
    sourceURL?: string;
    targetURL?: string;
}
export interface LoggerConfig {
    serviceName: string;
    logDir?: string;
    logLevel?: LogType;
    format?: string;
}
